def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    opp_c = 0
    my_c = 0
    for a, b in history:
        if b == 'C':
            opp_c += 1
        if a == 'C':
            my_c += 1

    last_me, last_opp = history[-1]

    # If the opponent has never defected, start by cooperating, then test with
    # one defection. If they forgive it, exploit them from then on.
    if opp_c == n:
        if n < 40:
            return 'C'
        my_d = n - my_c
        if my_d == 0:
            return 'D'
        if my_d == 1 and last_me == 'D' and last_opp == 'C' and n < 96:
            return 'C'
        return 'D'

    start = n - 8
    if start < 0:
        start = 0
    recent_len = n - start
    recent_opp_c = 0
    for i in range(start, n):
        if history[i][1] == 'C':
            recent_opp_c += 1

    d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            d_streak += 1
        else:
            break

    my_prev_c = 0
    opp_c_after_my_c = 0
    my_prev_d = 0
    opp_c_after_my_d = 0
    for i in range(1, n):
        if history[i - 1][0] == 'C':
            my_prev_c += 1
            if history[i][1] == 'C':
                opp_c_after_my_c += 1
        else:
            my_prev_d += 1
            if history[i][1] == 'C':
                opp_c_after_my_d += 1

    # Smoothed conditional probabilities of the opponent cooperating after
    # one of our recent actions.
    p_cc = (opp_c_after_my_c + 1) / (my_prev_c + 2)
    p_cd = (opp_c_after_my_d + 1) / (my_prev_d + 2)

    # Clear uncooperative opponents: defect to avoid being exploited.
    if n >= 12 and opp_c <= 2:
        return 'D'

    if recent_len >= 5 and recent_opp_c <= 1 and opp_c * 100 <= n * 30:
        if rng.random() < 0.07:
            return 'C'
        return 'D'

    # Opponent cooperated last round.
    if last_opp == 'C':
        # Exploit opponents who forgive our defects and are broadly cooperative.
        if my_prev_d >= 1:
            if p_cd >= 0.62 and opp_c * 100 >= n * 70 and recent_opp_c >= recent_len - 1:
                return 'D'
            if p_cd >= 0.78 and opp_c * 100 >= n * 60:
                return 'D'
            if n >= 85 and p_cd >= 0.52 and recent_opp_c >= recent_len - 2:
                return 'D'
            # If cooperation is not rewarded and defects are not punished,
            # defect often; this handles non-contingent/random-like opponents.
            if my_prev_d >= 2 and p_cd >= 0.5 and p_cc <= 0.68:
                if rng.random() < 0.8:
                    return 'D'
                return 'C'

        # Strongly cooperative recent behavior: mostly cooperate, with tiny probes.
        if opp_c * 100 >= n * 82 and recent_opp_c >= recent_len - 1:
            if rng.random() < 0.05:
                return 'D'
            return 'C'

        if opp_c * 100 >= n * 60 and recent_opp_c * 10 >= recent_len * 6:
            if rng.random() < 0.03:
                return 'D'
            return 'C'

        # Mostly uncooperative but just cooperated: defect to prevent exploitation.
        if opp_c * 100 <= n * 40:
            if rng.random() < 0.15 and n < 85:
                return 'C'
            return 'D'

        # Moderate/unstable opponents: stay cooperative unless occasionally probing.
        if rng.random() < 0.08:
            return 'D'
        return 'C'

    # Opponent defected last round.
    if opp_c * 100 <= n * 25:
        if rng.random() < 0.06:
            return 'C'
        return 'D'

    # If our cooperation was not rewarded, do not keep inviting exploitation.
    if p_cc < 0.52 and my_prev_c >= 2:
        return 'D'

    if d_streak >= 4:
        if rng.random() < 0.07 and n < 75:
            return 'C'
        return 'D'

    if last_me == 'D':
        # If they forgive defects, stay exploitative even after their own D.
        if p_cd >= 0.8 and opp_c * 100 >= n * 60 and d_streak == 1:
            return 'D'
        # Near the end against generally cooperative opponents, try to restore.
        if n >= 90 and opp_c * 100 >= n * 55 and p_cc >= 0.55:
            return 'C'
        if opp_c * 100 >= n * 55 and p_cc >= 0.6 and recent_opp_c >= recent_len - 2:
            return 'C'
        if rng.random() < 0.18:
            return 'C'
        return 'D'

    # Opponent defected while we cooperated: punish unless it looks like a rare
    # slip against a mostly cooperative opponent.
    if opp_c * 100 >= n * 78 and d_streak == 1 and recent_opp_c >= recent_len - 2:
        if rng.random() < 0.35:
            return 'C'

    if opp_c * 100 >= n * 60 and d_streak == 2 and recent_opp_c >= recent_len - 1:
        if rng.random() < 0.25:
            return 'C'

    return 'D'
